mapper.update:
UPDATE pending_orders
SET status = #{status},
    filled_order_id = #{filledOrderId, jdbcType=BIGINT},
    resolved_at = #{resolvedAt, jdbcType=TIMESTAMP}
WHERE id = #{id}

mapper.select:
SELECT id, account_id, stock_code, side, quantity, limit_price, status, filled_order_id, ordered_at, resolved_at
FROM pending_orders
WHERE id = #{id}
  AND account_id = #{accountId}
FOR UPDATE

SELECT id, account_id, stock_code, side, quantity, limit_price, status, filled_order_id, ordered_at, resolved_at
FROM pending_orders
WHERE account_id = #{accountId}
  AND stock_code = #{stockCode}
  AND status != 'FILLED'
ORDER BY ordered_at DESC

SELECT COALESCE(SUM(quantity), 0)
FROM pending_orders
WHERE account_id = #{accountId}
  AND stock_code = #{stockCode}
  AND side = 'SELL'
  AND status = 'PENDING'
